{"command":"kubectl get rolebinding clusterrolebinding --all-namespaces -o json 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
for rb in data['items']:
    if 'subjects' in rb:
        for subj in rb['subjects']:
            if 'config-reader' in str(subj):
                print(f\"{rb['kind']}: {rb['metadata']['name']} -> {subj}\")" 2>/dev/null"}

{"command":"kubectl get clusterrolebinding --all-namespaces -o json 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
for rb in data['items']:
    if rb['roleRef']['name'] == 'view':
        print(f\"ClusterRoleBinding: {rb['metadata']['name']}\")
        for subj in rb.get('subjects', []):
            print(f\"  Subject: {subj.get('kind')}/{subj.get('name')} ({subj.get('namespace', 'cluster-level')})\")" 2>/dev/null"}

